upd AS (
  UPDATE movimenti_bancari mb
  SET data_movimento = '2026-07-07'::date
  FROM src s
  JOIN movimenti_bancari_carichi c ON c.nome_file = s.nome_file
  WHERE mb.carico_id = c.id
    AND mb.data_movimento = '2026-07-06'
    AND left(coalesce(mb.descrizione, ''), 60) = s.prefix
  RETURNING mb.id
)
